# ---------------------------------------------------------------------------
# Desktop "disable sleep" naming: the pmset disablesleep switch shown on
# battery-less Macs (mini, Studio, Pro), where "closed-display mode" and lid
# wording make no sense. Same feature, desktop labels.
# ---------------------------------------------------------------------------
_DESKTOP_SLEEP = {
    "Disable system sleep": {"hu": "Rendszer elalvásának letiltása", "es": "Desactivar la suspensión del sistema", "fr": "Désactiver la veille du système", "de": "System-Ruhezustand deaktivieren", "zh-Hans": "禁用系统睡眠"},
    "Disable sleep": {"hu": "Alvás letiltása", "es": "Desactivar la suspensión", "fr": "Désactiver la veille", "de": "Ruhezustand deaktivieren", "zh-Hans": "禁用睡眠"},
    "disable system sleep": {"hu": "letiltsa a rendszer alvását", "es": "desactivar la suspensión del sistema", "fr": "désactiver la veille du système", "de": "den System-Ruhezustand zu deaktivieren", "zh-Hans": "禁用系统睡眠"},
    "switch the sleep override with the session": {"hu": "a munkamenettel váltsa az alvásfelülbírálást", "es": "cambiar la anulación de la suspensión según la sesión", "fr": "activer le contournement de la veille avec la session", "de": "die Ruhezustandssperre mit der Sitzung umzuschalten", "zh-Hans": "随会话切换禁用睡眠"},
    "The Mac won't sleep at all until you turn this off. The display still sleeps as usual.": {"hu": "A Mac egyáltalán nem alszik el, amíg ezt ki nem kapcsolja. A kijelző továbbra is szokás szerint elalszik.", "es": "El Mac no se suspenderá en absoluto hasta que desactives esto. La pantalla se sigue suspendiendo con normalidad.", "fr": "Le Mac ne se mettra pas du tout en veille tant que vous n’aurez pas désactivé ceci. L’écran continue de se mettre en veille normalement.", "de": "Der Mac schläft überhaupt nicht mehr ein, bis du dies ausschaltest. Das Display schläft weiterhin wie gewohnt ein.", "zh-Hans": "在你关闭此项之前，Mac 完全不会睡眠。显示器仍会照常睡眠。"},
    "Turns the sleep override on when a keep-awake session starts and off when it ends or Keepresso quits.": {"hu": "Bekapcsolja az alvásfelülbírálást, amikor egy ébrentartási munkamenet elindul, és kikapcsolja, amikor véget ér, vagy a Keepresso kilép.", "es": "Activa la anulación de la suspensión cuando comienza una sesión y la desactiva cuando termina o Keepresso se cierra.", "fr": "Active le contournement de la veille au début d’une session et le désactive à la fin ou quand Keepresso se ferme.", "de": "Schaltet die Ruhezustandssperre ein, wenn eine Wachhalte-Sitzung startet, und wieder aus, wenn sie endet oder Keepresso beendet wird.", "zh-Hans": "在保持唤醒会话开始时开启禁用睡眠，并在会话结束或 Keepresso 退出时关闭。"},
    "Stops the Mac from sleeping at all until you turn it off.": {"hu": "Megakadályozza, hogy a Mac egyáltalán elaludjon, amíg ki nem kapcsolja.", "es": "Evita que el Mac se suspenda en absoluto hasta que lo desactives.", "fr": "Empêche totalement le Mac de se mettre en veille jusqu’à ce que vous le désactiviez.", "de": "Verhindert, dass der Mac überhaupt einschläft, bis du es ausschaltest.", "zh-Hans": "彻底阻止 Mac 进入睡眠，直到你将其关闭。"},
    "Stops the Mac from sleeping at all, even with no session running. This flips a system setting that needs administrator rights: silent with the administrator helper installed (Preferences ▸ General), otherwise macOS asks for your password.": {"hu": "Megakadályozza, hogy a Mac egyáltalán elaludjon, még munkamenet nélkül is. Ez egy rendszergazdai jogokat igénylő rendszerbeállítást állít át: telepített rendszergazdai segéddel csendes (Beállítások ▸ Általános), egyébként a macOS bekéri a jelszavát.", "es": "Evita que el Mac se suspenda en absoluto, incluso sin ninguna sesión en marcha. Esto modifica un ajuste del sistema que requiere permisos de administrador: silencioso con el asistente de administrador instalado (Ajustes ▸ General), de lo contrario macOS pide tu contraseña.", "fr": "Empêche totalement le Mac de se mettre en veille, même sans session en cours. Cela modifie un réglage système qui nécessite des droits d’administrateur : silencieux avec l’assistant administrateur installé (Réglages ▸ Général), sinon macOS demande votre mot de passe.", "de": "Verhindert, dass der Mac überhaupt einschläft, selbst wenn keine Sitzung läuft. Dies ändert eine Systemeinstellung, die Administratorrechte erfordert: lautlos mit installiertem Administrator-Hilfsdienst (Einstellungen ▸ Allgemein), sonst fragt macOS nach deinem Passwort.", "zh-Hans": "即使没有运行中的会话，也彻底阻止 Mac 进入睡眠。这会切换一项需要管理员权限的系统设置：安装了管理员助理时为静默执行（偏好设置 ▸ 通用），否则 macOS 会索要你的密码。"},
    "Stops the Mac from sleeping at all, even with no session running. It works by flipping a system setting (pmset disablesleep), so it stays in effect until you turn it off, even if Keepresso quits. The display still sleeps as usual. “Only while brewing” ties it to the session instead, on when a keep-awake session starts, off when it ends or Keepresso quits (even after a crash). Both need administrator rights: silent with the administrator helper installed (see the top of this tab), otherwise macOS asks for your password, once per app run for “Only while brewing”.": {"hu": "Megakadályozza, hogy a Mac egyáltalán elaludjon, még munkamenet nélkül is. Egy rendszerbeállítás átállításával működik (pmset disablesleep), így addig marad érvényben, amíg ki nem kapcsolja, még akkor is, ha a Keepresso kilép. A kijelző továbbra is szokás szerint elalszik. A „Csak főzés közben” ehelyett a munkamenethez köti: bekapcsol, amikor egy ébrentartási munkamenet elindul, kikapcsol, amikor véget ér, vagy a Keepresso kilép (akár összeomlás után is). Mindkettőhöz rendszergazdai jogok kellenek: telepített rendszergazdai segéddel csendes (lásd e lap tetején), egyébként a macOS bekéri a jelszavát, a „Csak főzés közben” esetén alkalmazásindításonként egyszer.", "es": "Evita que el Mac se suspenda en absoluto, incluso sin ninguna sesión en marcha. Funciona modificando un ajuste del sistema (pmset disablesleep), por lo que sigue en efecto hasta que lo desactives, incluso si Keepresso se cierra. La pantalla se sigue suspendiendo con normalidad. «Solo mientras está en marcha» lo vincula a la sesión en su lugar, activándolo cuando comienza una sesión y desactivándolo cuando termina o Keepresso se cierra (incluso tras un bloqueo). Ambos requieren permisos de administrador: silencioso con el asistente de administrador instalado (mira arriba en esta pestaña), de lo contrario macOS pide tu contraseña, una vez por ejecución de la app para «Solo mientras está en marcha».", "fr": "Empêche totalement le Mac de se mettre en veille, même sans session en cours. Cela fonctionne en modifiant un réglage système (pmset disablesleep), qui reste donc actif jusqu’à ce que vous le désactiviez, même si Keepresso se ferme. L’écran continue de se mettre en veille normalement. « Uniquement pendant l’infusion » le relie plutôt à la session : activé au début d’une session, désactivé à la fin ou quand Keepresso se ferme (même après un plantage). Les deux nécessitent des droits d’administrateur : silencieux avec l’assistant administrateur installé (voir en haut de cet onglet), sinon macOS demande votre mot de passe, une fois par exécution de l’app pour « Uniquement pendant l’infusion ».", "de": "Verhindert, dass der Mac überhaupt einschläft, selbst wenn keine Sitzung läuft. Es funktioniert, indem es eine Systemeinstellung umschaltet (pmset disablesleep), die daher wirksam bleibt, bis du sie ausschaltest, selbst wenn Keepresso beendet wird. Das Display schläft weiterhin wie gewohnt ein. „Nur während des Brühens“ koppelt es stattdessen an die Sitzung: an, wenn eine Wachhalte-Sitzung startet, aus, wenn sie endet oder Keepresso beendet wird (auch nach einem Absturz). Beides braucht Administratorrechte: lautlos mit installiertem Administrator-Hilfsdienst (siehe oben in diesem Tab), sonst fragt macOS nach deinem Passwort, einmal pro App-Start für „Nur während des Brühens“.", "zh-Hans": "即使没有运行中的会话，也彻底阻止 Mac 进入睡眠。它的原理是切换一项系统设置（pmset disablesleep），因此在你将其关闭前会一直生效，即使 Keepresso 退出也是如此。显示器仍会照常睡眠。“仅在保持唤醒会话期间”则改为将其与会话绑定：在保持唤醒会话开始时打开，在会话结束或 Keepresso 退出时关闭（即使是崩溃之后）。两者都需要管理员权限：安装了管理员助理时为静默执行（见本标签页顶部），否则 macOS 会索要你的密码，“仅在保持唤醒会话期间”为每次 App 运行一次。"},
    "%@ before": {"hu": "%@ korábban", "es": "%@ antes", "fr": "%@ avant", "de": "%@ vorher", "zh-Hans": "提前 %@"},
}
APP.update(_DESKTOP_SLEEP)


# ---------------------------------------------------------------------------
# v1.15 thermal safety net, fan test, helper self-update, and the glass
# slider, plus the lid-closed scoping that followed. The reworded helper
# texts replace the retired pre-1.15 variants.
# ---------------------------------------------------------------------------
_THERMAL_V115 = {
    "(max %@)": {"hu": "(max. %@)", "es": "(máx. %@)", "fr": "(max %@)", "de": "(max. %@)", "zh-Hans": "（最高 %@）"},
    "15 seconds": {"hu": "15 másodperc", "es": "15 segundos", "fr": "15 secondes", "de": "15 Sekunden", "zh-Hans": "15 秒"},
    "A safety net for a Mac left running with the lid closed, slid into a bag with a session still holding it awake. It acts only in that trapped state: lid shut, with “Keep awake with the lid closed” overriding sleep. Watch macOS's own thermal pressure (works everywhere, “Serious” is where throttling bites) or specific temperature sensors, and if the reading stays over the threshold for the chosen time, Keepresso escalates: first, optionally, it boosts the fans (never below what the system chose, needs the administrator helper), and if it stays hot for the same time again, it pauses the session and switches the sleep override off, so the Mac can finally sleep and cool, telling you why in a notification. Opening the lid, or readings recovering, undoes everything: fan control returns to the system, the override comes back, and the session resumes. Die sensors on modern Macs routinely run at 90-100 °C under load, so thresholds around 95-100 °C are sensible.": {"hu": "Biztonsági háló egy olyan Machez, amelyet csukott fedéllel hagynak futni, táskába csúsztatva, miközben egy munkamenet még ébren tartja. Csak ebben a csapdahelyzetben lép működésbe: csukott fedél mellett, amikor az „Ébren tartás csukott fedéllel” felülbírálja az alvást. Figyeli a macOS saját hőterhelését (mindenhol működik, a „Súlyos” szintnél kezdődik a teljesítménykorlátozás) vagy konkrét hőmérséklet-érzékelőket, és ha az érték a választott ideig a küszöb felett marad, a Keepresso fokozatosan lép fel: először, választhatóan, felpörgeti a ventilátorokat (soha nem a rendszer által választott szint alá, ehhez a rendszergazdai segéd kell), majd ha ugyanennyi ideig továbbra is forró marad, szünetelteti a munkamenetet, és kikapcsolja az alvásfelülbírálást, hogy a Mac végre elaludhasson és lehűlhessen, egy értesítésben elmondva, miért. A fedél kinyitása vagy az értékek helyreállása mindent visszavon: a ventilátorvezérlés visszakerül a rendszerhez, a felülbírálás visszatér, és a munkamenet folytatódik. A modern Macek lapkahő-érzékelői terhelés alatt rendszerint 90–100 °C-on futnak, így a 95–100 °C körüli küszöbök ésszerűek.", "es": "Una red de seguridad para un Mac que sigue funcionando con la tapa cerrada, metido en una bolsa con una sesión que todavía lo mantiene despierto. Solo actúa en ese estado atrapado: con la tapa cerrada y «Mantener despierto con la tapa cerrada» anulando la suspensión. Vigila la propia presión térmica de macOS (funciona en todos los Mac, «Grave» es donde empieza la limitación) o sensores de temperatura concretos, y si la lectura se mantiene por encima del umbral durante el tiempo elegido, Keepresso escala: primero, opcionalmente, impulsa los ventiladores (nunca por debajo de lo que el sistema haya elegido, necesita el asistente de administrador), y si sigue caliente durante el mismo tiempo otra vez, pausa la sesión y desactiva la anulación de la suspensión, para que el Mac pueda por fin dormirse y enfriarse, explicándote por qué en una notificación. Abrir la tapa, o que las lecturas se recuperen, deshace todo: el control de los ventiladores vuelve al sistema, la anulación regresa, y la sesión se reanuda. Los sensores del die en los Mac modernos suelen rondar los 90-100 °C bajo carga, así que umbrales alrededor de 95-100 °C son razonables.", "fr": "Un filet de sécurité pour un Mac resté en fonctionnement capot fermé, glissé dans un sac alors qu’une session le maintient encore éveillé. Il n’agit que dans cet état de piégeage : capot fermé, avec « Garder éveillé capot fermé » qui empêche la veille. Surveillez la pression thermique propre à macOS (fonctionne partout, « Élevé » est le niveau où le throttling se fait sentir) ou des capteurs de température précis, et si la mesure reste au-dessus du seuil pendant la durée choisie, Keepresso passe à l’étape suivante : d’abord, en option, il booste les ventilateurs (jamais en dessous de ce que le système a choisi, nécessite l’assistant administrateur), et si la chaleur persiste pendant la même durée, il met la session en pause et désactive le contournement de la veille, afin que le Mac puisse enfin s’endormir et refroidir, en vous expliquant pourquoi dans une notification. Ouvrir le capot, ou un retour des mesures à la normale, annule tout : le contrôle des ventilateurs revient au système, le contournement se réactive, et la session reprend. Les capteurs du die (la puce) des Mac récents atteignent couramment 90-100 °C en charge, des seuils autour de 95-100 °C sont donc raisonnables.", "de": "Ein Sicherheitsnetz für einen Mac, der bei geschlossenem Deckel weiterläuft, in eine Tasche gesteckt, während eine Sitzung ihn noch wach hält. Es greift nur in dieser eingeschlossenen Lage: Deckel zu, während „Bei geschlossenem Deckel wach halten“ den Ruhezustand außer Kraft setzt. Es beobachtet entweder den thermischen Druck von macOS selbst (funktioniert überall, bei „Hoch“ setzt das Throttling ein) oder bestimmte Temperatursensoren, und wenn der Messwert für die gewählte Zeit über dem Schwellenwert bleibt, eskaliert Keepresso: Zuerst, optional, erhöht es die Lüfterdrehzahl (nie unter das, was das System gewählt hat, benötigt den Administrator-Hilfsdienst), und bleibt es für dieselbe Zeit erneut heiß, pausiert es die Sitzung und schaltet die Ruhezustandssperre aus, damit der Mac endlich schlafen und abkühlen kann, und teilt dir in einer Mitteilung mit, warum. Das Öffnen des Deckels oder sich erholende Messwerte machen alles rückgängig: Die Lüftersteuerung geht zurück an das System, die Sperre kehrt zurück, und die Sitzung wird fortgesetzt. Die-Sensoren an modernen Macs laufen unter Last routinemäßig bei 90-100 °C, Schwellenwerte um 95-100 °C sind daher sinnvoll.", "zh-Hans": "为合盖运行、被装进包里但仍有会话让它保持唤醒的 Mac 提供的安全网。它只在这种被困状态下起作用：盖子合上，且“合盖时保持唤醒”正在覆盖睡眠。它会关注 macOS 自身的热压力（在所有机型上都可用，“严重”是开始降频的临界点）或特定的温度传感器，如果读数在所选时间内持续超过阈值，Keepresso 会逐步升级：首先（可选）提升风扇转速（绝不会低于系统本身设定的转速，需要管理员助理），如果同样的时长内依旧过热，则会暂停会话并关闭睡眠覆盖，让 Mac 终于可以睡眠降温，并通过通知说明原因。打开盖子，或读数恢复正常，会撤销这一切：风扇控制权交还系统，睡眠覆盖恢复，会话继续。现代 Mac 的裸片（die）温度传感器在满载时经常处于 90-100 °C，因此阈值设在 95-100 °C 左右比较合理。"},
    "A small system service for the switches that need administrator rights: closed-display mode below, the thermal fan boost, and AWDL pausing in Gaming & Streaming. Without it, macOS asks for your password once per app run (and fan boost stays off entirely: fan control can't prompt). With it, everything is instant and silent: macOS asks once, when you approve the helper under Login Items, and the approval survives restarts and app updates. Updates never need a reinstall, the service replaces itself with the app. It can only flip those specific switches, everything it changes is restored if Keepresso quits or crashes, and you can remove it here at any time. It also puts the keepresso command-line tool on your PATH (Homebrew installs already have it). After removal, System Settings can keep showing a stale Login Items row until macOS refreshes its list. The status shown here is the real one.": {"hu": "Egy kis rendszerszolgáltatás azokhoz a kapcsolókhoz, amelyekhez rendszergazdai jogok kellenek: a lenti csukott fedél mód, a hővédelmi ventilátorfelpörgetés és az AWDL szüneteltetése a Játék és streamelésben. Nélküle a macOS alkalmazásindításonként egyszer bekéri a jelszavát (a ventilátorfelpörgetés pedig teljesen kikapcsolva marad: a ventilátorvezérlés nem tud jelszót kérni). Vele minden azonnali és csendes: a macOS egyszer kérdez, amikor jóváhagyja a segédet a Bejelentkezési elemek alatt, és a jóváhagyás túléli az újraindításokat és az alkalmazásfrissítéseket. A frissítésekhez soha nincs szükség újratelepítésre, a szolgáltatás magát cseréli le az alkalmazással együtt. Csak azokat a konkrét kapcsolókat tudja átállítani, minden, amit módosít, visszaáll, ha a Keepresso kilép vagy összeomlik, és bármikor eltávolíthatja itt. A keepresso parancssori eszközt is felteszi a PATH-ra (a Homebrew-telepítéseken ez már megvan). Eltávolítás után a Rendszerbeállítások még mutathat egy elavult Bejelentkezési elemek sort, amíg a macOS frissíti a listáját. Az itt látható állapot a valódi.", "es": "Un pequeño servicio del sistema para los interruptores que necesitan permisos de administrador: el modo con pantalla cerrada de abajo, el impulso térmico de los ventiladores y la pausa de AWDL en Juegos y streaming. Sin él, macOS pide tu contraseña una vez por ejecución de la app (y el impulso de los ventiladores se queda completamente desactivado: el control de los ventiladores no puede pedir permiso). Con él, todo es instantáneo y silencioso: macOS lo pide una sola vez, cuando apruebas el asistente en Ítems de inicio, y la aprobación sobrevive a reinicios y actualizaciones de la app. Las actualizaciones nunca necesitan una reinstalación, el servicio se reemplaza a sí mismo junto con la app. Solo puede activar esos interruptores concretos, todo lo que cambia se restaura si Keepresso se cierra o se bloquea, y puedes eliminarlo aquí en cualquier momento. También añade la herramienta de línea de comandos keepresso a tu PATH (las instalaciones con Homebrew ya la tienen). Tras eliminarlo, Ajustes del Sistema puede seguir mostrando una fila obsoleta en Ítems de inicio hasta que macOS actualice su lista. El estado que se muestra aquí es el real.", "fr": "Un petit service système pour les réglages qui nécessitent des droits d’administrateur : le mode écran fermé ci-dessous, le boost des ventilateurs et la pause AWDL dans Jeu et streaming. Sans lui, macOS demande votre mot de passe une fois par exécution de l’app (et le boost des ventilateurs reste totalement désactivé : le contrôle des ventilateurs ne peut pas demander de mot de passe). Avec lui, tout est instantané et silencieux : macOS ne demande qu’une fois, quand vous approuvez l’assistant sous Ouverture au démarrage, et cette approbation survit aux redémarrages et aux mises à jour de l’app. Les mises à jour ne nécessitent jamais de réinstallation, le service se remplace lui-même en même temps que l’app. Il ne peut activer que ces réglages précis, tout ce qu’il modifie est restauré si Keepresso se ferme ou plante, et vous pouvez le supprimer ici à tout moment. Il ajoute aussi l’outil en ligne de commande keepresso à votre PATH (les installations Homebrew l’ont déjà). Après sa suppression, Réglages Système peut continuer d’afficher une ligne obsolète sous Ouverture au démarrage jusqu’à ce que macOS actualise sa liste. Le statut affiché ici est le vrai.", "de": "Ein kleiner Systemdienst für die Schalter, die Administratorrechte benötigen: den Modus bei geschlossenem Display weiter unten, den thermischen Lüfter-Boost und das Pausieren von AWDL in Gaming und Streaming. Ohne ihn fragt macOS einmal pro App-Start nach deinem Passwort (und der Lüfter-Boost bleibt komplett aus: die Lüftersteuerung kann nicht nachfragen). Mit ihm ist alles sofort und lautlos: macOS fragt einmal, wenn du den Hilfsdienst unter Anmeldeobjekte genehmigst, und die Genehmigung übersteht Neustarts und App-Updates. Updates erfordern nie eine Neuinstallation, der Dienst ersetzt sich zusammen mit der App selbst. Er kann nur diese bestimmten Schalter umlegen, alles, was er ändert, wird wiederhergestellt, falls Keepresso beendet wird oder abstürzt, und du kannst ihn hier jederzeit entfernen. Außerdem fügt er das Kommandozeilenwerkzeug keepresso zu deinem PATH hinzu (Homebrew-Installationen haben es bereits). Nach der Entfernung können die Systemeinstellungen weiterhin eine veraltete Zeile unter Anmeldeobjekte anzeigen, bis macOS seine Liste aktualisiert. Der hier angezeigte Status ist der tatsächliche.", "zh-Hans": "面向需要管理员权限的开关的一项小型系统服务：下方的合盖模式、风扇提速，以及“游戏与串流”中的暂停 AWDL。没有它时，macOS 每次 App 运行都会索要一次密码（风扇提速则完全无法使用：风扇控制无法弹出密码提示）。安装后，一切都即时且静默：macOS 只在你于“登录项”中批准该助理时索要一次密码，此批准会在重启和 App 更新后依然有效。更新永远不需要重新安装，该服务会随 App 一起自我替换。它只能切换这些特定开关，它所改动的一切都会在 Keepresso 退出或崩溃后恢复原状，你也可以随时在此处移除它。它还会把 keepresso 命令行工具加入你的 PATH（通过 Homebrew 安装的已自带）。移除后，“系统设置”可能会继续显示一个过期的登录项条目，直到 macOS 刷新其列表。这里显示的状态才是真实状态。"},
    "Above": {"hu": "Felett", "es": "Por encima", "fr": "Au-dessus", "de": "Über", "zh-Hans": "高于"},
    "All good. Every fan followed the boost, and control is back with the system.": {"hu": "Minden rendben. Minden ventilátor követte a felpörgetést, és az irányítás visszakerült a rendszerhez.", "es": "Todo correcto. Todos los ventiladores respondieron al impulso, y el control ha vuelto al sistema.", "fr": "Tout va bien. Tous les ventilateurs ont suivi le boost, et le contrôle est revenu au système.", "de": "Alles in Ordnung. Jeder Lüfter ist dem Boost gefolgt, und die Steuerung liegt wieder beim System.", "zh-Hans": "一切正常。所有风扇都响应了提速，控制权已交还系统。"},
    "At or above": {"hu": "Legalább", "es": "Igual o por encima", "fr": "À partir de", "de": "Ab", "zh-Hans": "达到或高于"},
    "Boost fans first": {"hu": "Ventilátorok felpörgetése elsőként", "es": "Impulsar los ventiladores primero", "fr": "Booster d’abord les ventilateurs", "de": "Erst Lüfter hochfahren", "zh-Hans": "先提升风扇转速"},
    "Boosting fans and switching off closed-display mode during a heat pause need the administrator helper. Watching temperatures and pausing work without it. Installing asks for your approval once, in System Settings.": {"hu": "A ventilátorok felpörgetéséhez és a csukott fedél mód kikapcsolásához egy hőség miatti szünetben a rendszergazdai segéd kell. A hőmérsékletek figyelése és a szüneteltetés nélküle is működik. A telepítés egyszer kéri a jóváhagyását, a Rendszerbeállításokban.", "es": "Impulsar los ventiladores y desactivar el modo con pantalla cerrada durante una pausa por calor necesitan el asistente de administrador. Vigilar las temperaturas y pausar funcionan sin él. Instalarlo pide tu aprobación una sola vez, en Ajustes del Sistema.", "fr": "Booster les ventilateurs et désactiver le mode écran fermé lors d’une pause pour chaleur nécessitent l’assistant administrateur. Surveiller les températures et mettre en pause fonctionnent sans lui. L’installation demande votre approbation une fois, dans Réglages Système.", "de": "Für das Hochfahren der Lüfter und das Ausschalten des Modus bei geschlossenem Display während einer Hitzepause ist der Administrator-Hilfsdienst nötig. Das Beobachten der Temperaturen und das Pausieren funktionieren auch ohne ihn. Die Installation bittet einmal, in den Systemeinstellungen, um deine Zustimmung.", "zh-Hans": "在因过热暂停期间提升风扇转速和关闭合盖模式都需要管理员助理。没有它，监测温度和暂停功能仍可正常工作。安装只需在“系统设置”中批准一次。"},
    "Boosting fans needs the administrator helper (Preferences ▸ General). The rest of the thermal safety net still applies.": {"hu": "A ventilátorok felpörgetéséhez a rendszergazdai segéd kell (Beállítások ▸ Általános). A hővédelmi biztonsági háló többi része továbbra is érvényben marad.", "es": "Impulsar los ventiladores necesita el asistente de administrador (Ajustes ▸ General). El resto de la red de seguridad térmica sigue aplicándose.", "fr": "Booster les ventilateurs nécessite l’assistant administrateur (Réglages ▸ Général). Le reste du filet de sécurité thermique s’applique quand même.", "de": "Für das Hochfahren der Lüfter ist der Administrator-Hilfsdienst nötig (Einstellungen ▸ Allgemein). Der Rest des thermischen Sicherheitsnetzes gilt weiterhin.", "zh-Hans": "提升风扇转速需要管理员助理（偏好设置 ▸ 通用）。热安全网的其余部分仍照常生效。"},
    "Boosting fans to %d%% and reading back…": {"hu": "Ventilátorok felpörgetése %d%%-ra, majd visszaolvasás…", "es": "Impulsando los ventiladores al %d%% y leyendo…", "fr": "Boost des ventilateurs à %d%% et lecture des valeurs…", "de": "Lüfter werden auf %d%% hochgefahren, Werte werden ausgelesen…", "zh-Hans": "正在将风扇转速提升到 %d%% 并读取反馈…"},
    "Closed-display mode left on": {"hu": "A csukott fedél mód bekapcsolva maradt", "es": "Modo con pantalla cerrada sigue activado", "fr": "Mode écran fermé laissé activé", "de": "Modus bei geschlossenem Display bleibt aktiv", "zh-Hans": "合盖模式仍处于开启状态"},
    "Fan %d: %@ → %@ rpm": {"hu": "%d. ventilátor: %@ → %@ rpm", "es": "Ventilador %d: %@ → %@ rpm", "fr": "Ventilateur %d : %@ → %@ rpm", "de": "Lüfter %d: %@ → %@ rpm", "zh-Hans": "风扇 %d：%@ → %@ rpm"},
    "Fan boost": {"hu": "Ventilátorfelpörgetés", "es": "Impulso de los ventiladores", "fr": "Boost des ventilateurs", "de": "Lüfter-Boost", "zh-Hans": "风扇提速"},
    "Fan boost ended": {"hu": "A ventilátorfelpörgetés véget ért", "es": "Impulso de los ventiladores finalizado", "fr": "Fin du boost des ventilateurs", "de": "Lüfter-Boost beendet", "zh-Hans": "风扇提速已结束"},
    "Fans boosted to %d%% to cool the Mac": {"hu": "A ventilátorok %d%%-ra felpörgetve, hogy lehűtsék a Macet", "es": "Ventiladores impulsados al %d%% para enfriar el Mac", "fr": "Ventilateurs boostés à %d%% pour refroidir le Mac", "de": "Lüfter auf %d%% hochgefahren, um den Mac abzukühlen", "zh-Hans": "风扇已提速至 %d%% 以帮助 Mac 降温"},
    "Fans not boosted": {"hu": "A ventilátorok nem pörögtek fel", "es": "Ventiladores no impulsados", "fr": "Ventilateurs non boostés", "de": "Lüfter nicht hochgefahren", "zh-Hans": "风扇未提速"},
    "Helper installed. Closed-display mode, fan boost, and AWDL pausing work without password prompts.": {"hu": "A segéd telepítve. A csukott fedél mód, a ventilátorfelpörgetés és az AWDL szüneteltetése jelszó nélkül működik.", "es": "Asistente instalado. El modo con pantalla cerrada, el impulso de los ventiladores y la pausa de AWDL funcionan sin peticiones de contraseña.", "fr": "Assistant installé. Le mode écran fermé, le boost des ventilateurs et la pause AWDL fonctionnent sans demande de mot de passe.", "de": "Hilfsdienst installiert. Der Modus bei geschlossenem Display, der Lüfter-Boost und das Pausieren von AWDL funktionieren ohne Passwortabfragen.", "zh-Hans": "助理已安装。合盖模式、风扇提速和暂停 AWDL 均可在无密码提示下使用。"},
    "Hottest sensor during the test: %@.": {"hu": "A legforróbb érzékelő a teszt alatt: %@.", "es": "Sensor más caliente durante la prueba: %@.", "fr": "Capteur le plus chaud pendant le test : %@.", "de": "Heißester Sensor während des Tests: %@.", "zh-Hans": "测试期间最高温传感器：%@。"},
    "How see-through the menu-bar dropdown is. Frosty (0%) backs its glass with blur and a wash of the window color, so text stays crisp on any wallpaper. Sliding toward 100% thins that backing away until the panel is the system's bare Liquid Glass, letting the desktop shine through, with some contrast cost on busy or very dark wallpapers. Changes apply instantly, only to the dropdown (windows like this one keep their standard look), and the system's Reduce Transparency accessibility setting always wins.": {"hu": "Mennyire áttetsző a menüsori lenyíló panel. Fagyos (0%) állapotban az üveghatás elmosódással és az ablakszín rétegével van alábélelve, így a szöveg minden háttérképen éles marad. A 100% felé csúsztatva ez az alábélelés elvékonyodik, amíg a panel a rendszer csupasz Liquid Glass felülete nem lesz, átengedve az asztal látványát, ami zsúfolt vagy nagyon sötét háttérképeken némi kontrasztveszteséggel jár. A változtatások azonnal érvénybe lépnek, csak a lenyíló panelen (az ehhez hasonló ablakok megtartják a szokásos megjelenésüket), és a rendszer Áttetszőség csökkentése kisegítő lehetőség beállítása mindig elsőbbséget élvez.", "es": "Cuán transparente es el desplegable de la barra de menús. Escarchado (0%) respalda su cristal con desenfoque y un baño del color de la ventana, así el texto se mantiene nítido sobre cualquier fondo de pantalla. Deslizar hacia el 100% adelgaza ese respaldo hasta que el panel queda como el Liquid Glass puro del sistema, dejando que el escritorio se transparente, con cierto coste de contraste en fondos de pantalla recargados o muy oscuros. Los cambios se aplican al instante, solo al desplegable (ventanas como esta mantienen su aspecto habitual), y el ajuste de accesibilidad Reducir transparencia del sistema siempre prevalece.", "fr": "À quel point le menu déroulant de la barre des menus est transparent. Givré (0 %) habille son verre de flou et d’un voile de la couleur de la fenêtre, pour que le texte reste net sur n’importe quel fond d’écran. Glisser vers 100 % amincit peu à peu ce voile jusqu’à ce que le panneau devienne le Liquid Glass nu du système, laissant transparaître le bureau, avec un certain coût de contraste sur des fonds d’écran chargés ou très sombres. Les changements s’appliquent instantanément, uniquement au menu déroulant (les fenêtres comme celle-ci gardent leur apparence standard), et le réglage d’accessibilité Réduire la transparence du système l’emporte toujours.", "de": "Wie durchsichtig das Dropdown-Menü der Menüleiste ist. Frostig (0%) unterlegt sein Glas mit Unschärfe und einem Hauch der Fensterfarbe, sodass Text auf jedem Hintergrundbild scharf bleibt. Ein Schieben in Richtung 100% dünnt diese Unterlage aus, bis das Panel dem reinen Liquid Glass des Systems entspricht und den Schreibtisch durchscheinen lässt, mit etwas Kontrastverlust bei unruhigen oder sehr dunklen Hintergrundbildern. Änderungen wirken sofort und nur auf das Dropdown-Menü (Fenster wie dieses behalten ihr Standardaussehen), und die Bedienungshilfen-Einstellung „Transparenz reduzieren“ des Systems hat immer Vorrang.", "zh-Hans": "菜单栏下拉面板的透明程度。“磨砂”（0%）会在玻璃背后叠加模糊效果和一层窗口色调，让文字在任何桌面背景下都保持清晰。向 100% 滑动会逐渐减薄这层背景，直至面板呈现系统原生的裸 Liquid Glass 效果，让桌面透出来，在繁杂或很暗的桌面背景下会有一定的对比度损失。更改会立即生效，且只影响这个下拉面板（像这样的窗口仍保持标准外观），系统的“降低透明度”辅助功能设置始终优先。"},
    "Install a small helper service so closed-display mode, the thermal fan boost, and AWDL pausing work without password prompts. macOS will ask you to allow it in System Settings, once. Nothing else changes.": {"hu": "Telepítsen egy kis segédszolgáltatást, hogy a csukott fedél mód, a hővédelmi ventilátorfelpörgetés és az AWDL szüneteltetése jelszó nélkül működjön. A macOS egyszer megkéri, hogy engedélyezze a Rendszerbeállításokban. Semmi más nem változik.", "es": "Instala un pequeño servicio asistente para que el modo con pantalla cerrada, el impulso térmico de los ventiladores y la pausa de AWDL funcionen sin peticiones de contraseña. macOS te pedirá permitirlo en Ajustes del Sistema, una sola vez. Nada más cambia.", "fr": "Installez un petit service d’assistance pour que le mode écran fermé, le boost des ventilateurs et la pause AWDL fonctionnent sans demande de mot de passe. macOS vous demandera de l’autoriser dans Réglages Système, une seule fois. Rien d’autre ne change.", "de": "Installiere einen kleinen Hilfsdienst, damit der Modus bei geschlossenem Display, der thermische Lüfter-Boost und das Pausieren von AWDL ohne Passwortabfragen funktionieren. macOS bittet dich einmal in den Systemeinstellungen um Erlaubnis. Sonst ändert sich nichts.", "zh-Hans": "安装一个小型助理服务，让合盖模式、风扇提速和暂停 AWDL 都能在无密码提示下使用。macOS 会要求你在“系统设置”中批准一次，其他一切都不会改变。"},
    "Keepresso paused for heat but can't switch off closed-display mode without the administrator helper (Preferences ▸ General).": {"hu": "A Keepresso szüneteltetve lett a hőség miatt, de a rendszergazdai segéd nélkül nem tudja kikapcsolni a csukott fedél módot (Beállítások ▸ Általános).", "es": "Keepresso se pausó por calor pero no puede desactivar el modo con pantalla cerrada sin el asistente de administrador (Ajustes ▸ General).", "fr": "Keepresso s’est mis en pause pour cause de chaleur, mais ne peut pas désactiver le mode écran fermé sans l’assistant administrateur (Réglages ▸ Général).", "de": "Keepresso hat wegen Hitze pausiert, kann aber ohne den Administrator-Hilfsdienst (Einstellungen ▸ Allgemein) den Modus bei geschlossenem Display nicht ausschalten.", "zh-Hans": "Keepresso 已因过热暂停，但没有管理员助理（偏好设置 ▸ 通用）就无法关闭合盖模式。"},
    "Looking for heat? “Pause when running hot” lives in General ▸ Thermal: a safety net that overrides these rules when the Mac runs hot with the lid closed.": {"hu": "Hőt keres? A „Szüneteltetés forróság esetén” az Általános ▸ Hővédelem részben található: egy biztonsági háló, amely felülbírálja ezeket a szabályokat, amikor a Mac csukott fedéllel forró lesz.", "es": "¿Buscas el calor? «Pausar cuando el Mac esté muy caliente» está en General ▸ Térmico: una red de seguridad que anula estas reglas cuando el Mac se calienta demasiado con la tapa cerrada.", "fr": "Vous cherchez la chaleur ? « Mettre en pause si le Mac chauffe » se trouve dans Général ▸ Thermique : un filet de sécurité qui prend le pas sur ces règles quand le Mac chauffe capot fermé.", "de": "Suchst du nach Hitze? „Pause bei Überhitzung“ findest du unter Allgemein ▸ Temperatur: ein Sicherheitsnetz, das diese Regeln außer Kraft setzt, wenn der Mac bei geschlossenem Deckel heiß läuft.", "zh-Hans": "在找过热相关设置？“过热时暂停”位于“通用 ▸ 温控”：这是一项安全网，会在合盖且 Mac 过热时覆盖这些规则。"},
    "No fans were found to test.": {"hu": "Nem található tesztelhető ventilátor.", "es": "No se encontraron ventiladores para probar.", "fr": "Aucun ventilateur trouvé à tester.", "de": "Keine Lüfter zum Testen gefunden.", "zh-Hans": "未找到可测试的风扇。"},
    "No temperature sensors found on this Mac. The thermal pressure signal above still works.": {"hu": "Nem található hőmérséklet-érzékelő ezen a Macen. A fenti hőterhelés-jelzés továbbra is működik.", "es": "No se encontraron sensores de temperatura en este Mac. La señal de presión térmica de arriba sigue funcionando.", "fr": "Aucun capteur de température trouvé sur ce Mac. Le signal de pression thermique ci-dessus fonctionne quand même.", "de": "Auf diesem Mac wurden keine Temperatursensoren gefunden. Das Signal für den thermischen Druck oben funktioniert weiterhin.", "zh-Hans": "此 Mac 上未找到温度传感器。上方的热压力信号仍然可用。"},
    "One step left, in System Settings: allow Keepresso under Login Items, and these unlock by themselves.": {"hu": "Egy lépés van hátra a Rendszerbeállításokban: engedélyezze a Keepressót a Bejelentkezési elemek alatt, és ezek maguktól feloldódnak.", "es": "Queda un paso, en Ajustes del Sistema: permite Keepresso en Ítems de inicio, y estos se desbloquean por sí solos.", "fr": "Encore une étape, dans Réglages Système : autorisez Keepresso sous Ouverture au démarrage, et ces réglages se débloquent d’eux-mêmes.", "de": "Noch ein Schritt in den Systemeinstellungen: Erlaube Keepresso unter Anmeldeobjekte, dann schalten sich diese von selbst frei.", "zh-Hans": "还差一步，在“系统设置”中：在“登录项”里允许 Keepresso，这些功能便会自动解锁。"},
    "Pause when running hot": {"hu": "Szüneteltetés forróság esetén", "es": "Pausar cuando el Mac esté muy caliente", "fr": "Mettre en pause si le Mac chauffe", "de": "Pause bei Überhitzung", "zh-Hans": "过热时暂停"},
    "Reading the fans…": {"hu": "Ventilátorok leolvasása…", "es": "Leyendo los ventiladores…", "fr": "Lecture des ventilateurs…", "de": "Lüfter werden ausgelesen…", "zh-Hans": "正在读取风扇状态…"},
    "Run a quick check: the fans step through three boost levels for about 12 seconds, with readings at each, then control goes back to the system.": {"hu": "Futtasson egy gyors ellenőrzést: a ventilátorok három felpörgetési szinten mennek végig, egyenként körülbelül 12 másodpercig, mindegyiknél leolvasással, majd az irányítás visszakerül a rendszerhez.", "es": "Ejecuta una comprobación rápida: los ventiladores pasan por tres niveles de impulso durante unos 12 segundos, con lecturas en cada uno, y después el control vuelve al sistema.", "fr": "Lancez une vérification rapide : les ventilateurs passent par trois niveaux de boost pendant environ 12 secondes, avec une mesure à chaque niveau, puis le contrôle revient au système.", "de": "Führe eine schnelle Prüfung aus: Die Lüfter durchlaufen drei Boost-Stufen für etwa 12 Sekunden, mit Messwerten bei jeder Stufe, danach geht die Steuerung zurück an das System.", "zh-Hans": "快速检查一下：风扇会依次经过三个提速档位，每档持续约 12 秒并读取数据，随后控制权交还系统。"},
    "Running hot (%d °C), letting the Mac cool down": {"hu": "A Mac forró (%d °C), lehűlhet", "es": "Muy caliente (%d °C), dejando que el Mac se enfríe", "fr": "Le Mac chauffe (%d °C), il peut refroidir", "de": "Läuft heiß (%d °C), Mac darf abkühlen", "zh-Hans": "过热（%d °C），正在让 Mac 降温"},
    "Running hot, letting the Mac cool down": {"hu": "A Mac forró, lehűlhet", "es": "Muy caliente, dejando que el Mac se enfríe", "fr": "Le Mac chauffe, il peut refroidir", "de": "Läuft heiß, Mac darf abkühlen", "zh-Hans": "过热，正在让 Mac 降温"},
    "See-through": {"hu": "Áttetszőség", "es": "Transparencia", "fr": "Transparence", "de": "Durchsichtigkeit", "zh-Hans": "透明度"},
    "Some selected sensors are unavailable on this Mac.": {"hu": "Néhány kiválasztott érzékelő nem érhető el ezen a Macen.", "es": "Algunos de los sensores seleccionados no están disponibles en este Mac.", "fr": "Certains capteurs sélectionnés ne sont pas disponibles sur ce Mac.", "de": "Einige ausgewählte Sensoren sind auf diesem Mac nicht verfügbar.", "zh-Hans": "部分已选传感器在此 Mac 上不可用。"},
    "Stop": {"hu": "Leállítás", "es": "Detener", "fr": "Arrêter", "de": "Stoppen", "zh-Hans": "停止"},
    "Sustained for": {"hu": "Fennállási idő", "es": "Mantenido durante", "fr": "Maintenu pendant", "de": "Anhaltend für", "zh-Hans": "持续时长"},
    "Switching off closed-display mode during a heat pause needs the administrator helper. Watching temperatures and pausing work without it. Installing asks for your approval once, in System Settings.": {"hu": "A csukott fedél mód kikapcsolásához egy hőség miatti szünetben a rendszergazdai segéd kell. A hőmérsékletek figyelése és a szüneteltetés nélküle is működik. A telepítés egyszer kéri a jóváhagyását, a Rendszerbeállításokban.", "es": "Desactivar el modo con pantalla cerrada durante una pausa por calor necesita el asistente de administrador. Vigilar las temperaturas y pausar funcionan sin él. Instalarlo pide tu aprobación una sola vez, en Ajustes del Sistema.", "fr": "Désactiver le mode écran fermé lors d’une pause pour chaleur nécessite l’assistant administrateur. Surveiller les températures et mettre en pause fonctionnent sans lui. L’installation demande votre approbation une fois, dans Réglages Système.", "de": "Für das Ausschalten des Modus bei geschlossenem Display während einer Hitzepause ist der Administrator-Hilfsdienst nötig. Das Beobachten der Temperaturen und das Pausieren funktionieren auch ohne ihn. Die Installation bittet einmal, in den Systemeinstellungen, um deine Zustimmung.", "zh-Hans": "在因过热暂停期间关闭合盖模式需要管理员助理。没有它，监测温度和暂停功能仍可正常工作。安装只需在“系统设置”中批准一次。"},
    "System thermal pressure": {"hu": "Rendszer hőterhelése", "es": "Presión térmica del sistema", "fr": "Pression thermique du système", "de": "Thermischer Druck des Systems", "zh-Hans": "系统热压力"},
    "Temperature sensors": {"hu": "Hőmérséklet-érzékelők", "es": "Sensores de temperatura", "fr": "Capteurs de température", "de": "Temperatursensoren", "zh-Hans": "温度传感器"},
    "Temperature threshold": {"hu": "Hőmérsékleti küszöb", "es": "Umbral de temperatura", "fr": "Seuil de température", "de": "Temperaturschwellenwert", "zh-Hans": "温度阈值"},
    "Temperatures recovered": {"hu": "A hőmérsékletek helyreálltak", "es": "Temperaturas recuperadas", "fr": "Températures redescendues", "de": "Temperaturen erholt", "zh-Hans": "温度已恢复"},
    "Test Fans": {"hu": "Ventilátorteszt", "es": "Probar ventiladores", "fr": "Tester les ventilateurs", "de": "Lüfter testen", "zh-Hans": "测试风扇"},
    "Test stopped. Fan control is back with the system.": {"hu": "A teszt leállt. A ventilátorvezérlés visszakerült a rendszerhez.", "es": "Prueba detenida. El control de los ventiladores ha vuelto al sistema.", "fr": "Test arrêté. Le contrôle des ventilateurs est revenu au système.", "de": "Test gestoppt. Die Lüftersteuerung liegt wieder beim System.", "zh-Hans": "测试已停止。风扇控制权已交还系统。"},
    "The Mac has cooled down. Keepresso is back to normal control.": {"hu": "A Mac lehűlt. A Keepresso visszatért a normál vezérléshez.", "es": "El Mac se ha enfriado. Keepresso ha vuelto al control normal.", "fr": "Le Mac a refroidi. Keepresso a repris un contrôle normal.", "de": "Der Mac ist abgekühlt. Keepresso ist zur normalen Steuerung zurückgekehrt.", "zh-Hans": "Mac 已降温。Keepresso 已恢复正常控制。"},
    "The administrator helper didn't accept fan control. Check its status in the section above, then run the test again.": {"hu": "A rendszergazdai segéd nem fogadta el a ventilátorvezérlést. Ellenőrizze az állapotát a fenti szakaszban, majd futtassa újra a tesztet.", "es": "El asistente de administrador no aceptó el control de los ventiladores. Comprueba su estado en la sección de arriba y vuelve a ejecutar la prueba.", "fr": "L’assistant administrateur n’a pas accepté le contrôle des ventilateurs. Vérifiez son état dans la section ci-dessus, puis relancez le test.", "de": "Der Administrator-Hilfsdienst hat die Lüftersteuerung nicht angenommen. Prüfe seinen Status im Abschnitt oben, und führe den Test dann erneut aus.", "zh-Hans": "管理员助理未能接受风扇控制。请查看上方区块中的状态，然后重新运行测试。"},
    "The administrator helper didn't accept the fan boost. The rest of the thermal safety net still applies.": {"hu": "A rendszergazdai segéd nem fogadta el a ventilátorfelpörgetést. A hővédelmi biztonsági háló többi része továbbra is érvényben marad.", "es": "El asistente de administrador no aceptó el impulso de los ventiladores. El resto de la red de seguridad térmica sigue aplicándose.", "fr": "L’assistant administrateur n’a pas accepté le boost des ventilateurs. Le reste du filet de sécurité thermique s’applique quand même.", "de": "Der Administrator-Hilfsdienst hat den Lüfter-Boost nicht angenommen. Der Rest des thermischen Sicherheitsnetzes gilt weiterhin.", "zh-Hans": "管理员助理未能接受风扇提速。热安全网的其余部分仍照常生效。"},
    "The administrator helper is still updating itself to this version of Keepresso. Fan boost engages once that finishes, and the rest of the thermal safety net still applies.": {"hu": "A rendszergazdai segéd még frissíti magát a Keepresso ezen verziójára. A ventilátorfelpörgetés a frissítés végeztével lép életbe, és a hővédelmi biztonsági háló többi része továbbra is érvényben marad.", "es": "El asistente de administrador todavía se está actualizando a esta versión de Keepresso. El impulso de los ventiladores se activa en cuanto termine, y el resto de la red de seguridad térmica sigue aplicándose.", "fr": "L’assistant administrateur est encore en train de se mettre à jour vers cette version de Keepresso. Le boost des ventilateurs s’active une fois cette mise à jour terminée, et le reste du filet de sécurité thermique s’applique quand même.", "de": "Der Administrator-Hilfsdienst aktualisiert sich noch selbst auf diese Version von Keepresso. Der Lüfter-Boost greift, sobald das abgeschlossen ist, und der Rest des thermischen Sicherheitsnetzes gilt weiterhin.", "zh-Hans": "管理员助理仍在自我更新到此版本的 Keepresso。更新完成后风扇提速才会生效，热安全网的其余部分仍照常生效。"},
    "The fan test needs the administrator helper.": {"hu": "A ventilátorteszthez a rendszergazdai segéd kell.", "es": "La prueba de ventiladores necesita el asistente de administrador.", "fr": "Le test des ventilateurs nécessite l’assistant administrateur.", "de": "Der Lüftertest benötigt den Administrator-Hilfsdienst.", "zh-Hans": "风扇测试需要管理员助理。"},
    "The fans are boosted for heat right now, so the test stays off until readings recover.": {"hu": "A ventilátorok jelenleg fel vannak pörgetve a hőség miatt, ezért a teszt kikapcsolva marad, amíg az értékek helyre nem állnak.", "es": "Los ventiladores están impulsados por el calor ahora mismo, así que la prueba permanece desactivada hasta que las lecturas se recuperen.", "fr": "Les ventilateurs sont actuellement boostés pour la chaleur, le test reste donc désactivé tant que les mesures ne redescendent pas.", "de": "Die Lüfter sind gerade wegen Hitze hochgefahren, daher bleibt der Test deaktiviert, bis sich die Messwerte erholen.", "zh-Hans": "风扇目前正因过热而提速，因此测试功能会保持关闭，直到读数恢复正常。"},
    "The fans didn't follow the boost, so this Mac's firmware likely refuses manual fan control. The rest of the thermal safety net still works, the boost stage will just be skipped.": {"hu": "A ventilátorok nem követték a felpörgetést, így ennek a Macnek a firmware-je valószínűleg elutasítja a kézi ventilátorvezérlést. A hővédelmi biztonsági háló többi része továbbra is működik, csak a felpörgetési szakasz marad ki.", "es": "Los ventiladores no respondieron al impulso, así que probablemente el firmware de este Mac rechaza el control manual de los ventiladores. El resto de la red de seguridad térmica sigue funcionando, solo se omitirá la fase de impulso.", "fr": "Les ventilateurs n’ont pas suivi le boost, le micrologiciel de ce Mac refuse probablement le contrôle manuel des ventilateurs. Le reste du filet de sécurité thermique fonctionne quand même, l’étape de boost sera simplement ignorée.", "de": "Die Lüfter sind dem Boost nicht gefolgt, die Firmware dieses Macs verweigert manuelle Lüftersteuerung vermutlich. Der Rest des thermischen Sicherheitsnetzes funktioniert weiterhin, die Boost-Stufe wird einfach übersprungen.", "zh-Hans": "风扇未响应提速指令，此 Mac 的固件很可能拒绝手动风扇控制。热安全网的其余部分仍正常工作，只是会跳过提速阶段。"},
    "The firmware kept refusing manual fan control, so the fans are back with the system. The rest of the thermal safety net still applies.": {"hu": "A firmware továbbra is elutasította a kézi ventilátorvezérlést, ezért a ventilátorok visszakerültek a rendszerhez. A hővédelmi biztonsági háló többi része továbbra is érvényben marad.", "es": "El firmware siguió rechazando el control manual de los ventiladores, así que estos han vuelto al sistema. El resto de la red de seguridad térmica sigue aplicándose.", "fr": "Le micrologiciel a continué de refuser le contrôle manuel des ventilateurs, ils sont donc revenus au système. Le reste du filet de sécurité thermique s’applique quand même.", "de": "Die Firmware hat die manuelle Lüftersteuerung weiterhin verweigert, daher liegen die Lüfter wieder beim System. Der Rest des thermischen Sicherheitsnetzes gilt weiterhin.", "zh-Hans": "固件持续拒绝手动风扇控制，因此风扇控制权已交还系统。热安全网的其余部分仍照常生效。"},
    "The helper is updating itself to this version of Keepresso (no password needed). Fan boost and this test unlock when it finishes, usually under a minute.": {"hu": "A segéd frissíti magát a Keepresso ezen verziójára (jelszó nem szükséges). A ventilátorfelpörgetés és ez a teszt a frissítés végeztével oldódik fel, általában egy percen belül.", "es": "El asistente se está actualizando a esta versión de Keepresso (no hace falta contraseña). El impulso de los ventiladores y esta prueba se desbloquean cuando termine, normalmente en menos de un minuto.", "fr": "L’assistant est en train de se mettre à jour vers cette version de Keepresso (aucun mot de passe requis). Le boost des ventilateurs et ce test se débloquent une fois la mise à jour terminée, généralement en moins d’une minute.", "de": "Der Hilfsdienst aktualisiert sich selbst auf diese Version von Keepresso (kein Passwort nötig). Der Lüfter-Boost und dieser Test schalten sich frei, sobald das abgeschlossen ist, meist innerhalb einer Minute.", "zh-Hans": "助理正在自我更新到此版本的 Keepresso（无需密码）。更新完成后风扇提速和此测试便会解锁，通常不到一分钟。"},
    "The helper service is updating itself to this version of Keepresso in the background. No reinstall or password is needed. Features new to this version wait until it finishes, usually under a minute.": {"hu": "A segédszolgáltatás a háttérben frissíti magát a Keepresso ezen verziójára. Nincs szükség újratelepítésre vagy jelszóra. Az ebben a verzióban új funkciók várnak, amíg ez befejeződik, általában egy percen belül.", "es": "El servicio del asistente se está actualizando a esta versión de Keepresso en segundo plano. No hace falta reinstalarlo ni introducir una contraseña. Las funciones nuevas de esta versión esperan hasta que termine, normalmente en menos de un minuto.", "fr": "Le service d’assistance est en train de se mettre à jour vers cette version de Keepresso en arrière-plan. Aucune réinstallation ni mot de passe n’est nécessaire. Les fonctionnalités nouvelles de cette version attendent la fin de la mise à jour, généralement moins d’une minute.", "de": "Der Hilfsdienst aktualisiert sich im Hintergrund selbst auf diese Version von Keepresso. Weder eine Neuinstallation noch ein Passwort ist nötig. Neue Funktionen dieser Version warten, bis das abgeschlossen ist, meist innerhalb einer Minute.", "zh-Hans": "助理服务正在后台自我更新到此版本的 Keepresso，无需重新安装或输入密码。此版本新增的功能会等待更新完成，通常不到一分钟。"},
    "Window transparency": {"hu": "Ablak áttetszősége", "es": "Transparencia de la ventana", "fr": "Transparence de la fenêtre", "de": "Fenstertransparenz", "zh-Hans": "窗口透明度"},
}
APP.update(_THERMAL_V115)


